// Render an ETA duration the way an admin reads "wie lange dauert es noch":
//   <1 min  → "any second"
//   <60 min → "in 12 min"
//   same day → "in 2h 15m"
//   multi-day → "in 3 days"
//
// Hoisted from DocumentIndexingSection.vue so LiveProgressPanel can render
// Takes a `tf` helper (Tolgee resolve-with-fallback) so labels stay localised.

export type TFn = (key: string, fallback: string) => string;

export function formatETA(eta: Date | null, tf: TFn): string {
  if (!eta) return '';
  const now = Date.now();
  const ms = eta.getTime() - now;
  const minutes = Math.round(ms / 60000);
  if (minutes < 1) return tf('fulltext_velocity_eta_imminent', 'any second');
  if (minutes < 60) {
    return `${tf('fulltext_velocity_eta_in', 'in')} ${minutes} min`;
  }
  if (minutes < 24 * 60) {
    const hours = Math.floor(minutes / 60);
    const rest = minutes % 60;
    return rest > 0
      ? `${tf('fulltext_velocity_eta_in', 'in')} ${hours}h ${rest}m`
      : `${tf('fulltext_velocity_eta_in', 'in')} ${hours}h`;
  }
  const days = Math.round(ms / (24 * 60 * 60 * 1000));
  return `${tf('fulltext_velocity_eta_in', 'in')} ${days} ${tf('fulltext_velocity_eta_days', 'days')}`;
}
