<template>
  <span
    class="inline-flex items-center gap-1.5 rounded-full px-2.5 py-0.5 text-xs font-semibold"
    :class="badge.class"
  >
    <Icon :icon="badge.icon" class="size-3.5" />
    {{ badge.label }}
  </span>
</template>

<script lang="ts">
import { defineComponent, computed } from 'vue';
import { useTranslate } from '@tolgee/vue';
import { Icon } from '@iconify/vue';

export default defineComponent({
  name: 'IndexHealthBadge',
  components: { Icon },
  props: {
    indexPct: { type: Number, required: true },
    vectorPct: { type: Number, required: true },
    anyVectorEnabled: { type: Boolean, default: false },
    reindexActive: { type: Boolean, default: false },
    failedCount: { type: Number, default: 0 },
  },
  setup(props) {
    const { t } = useTranslate();
    const tf = (k: string, f: string) => {
      const v = t.value(k);
      return v !== k ? v : f;
    };

    const badge = computed(() => {
      // out of sync: hard failures or coverage critically low
      if (props.failedCount > 0 || props.indexPct < 80) {
        return {
          class: 'bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400',
          icon: 'mdi:alert-circle',
          label: tf('fulltext_health_broken', 'Index out of sync'),
        };
      }
      // catching up: reindex running, or coverage in [80,95)
      if (props.reindexActive || props.indexPct < 95) {
        return {
          class: 'bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-400',
          icon: 'mdi:alert',
          label: tf('fulltext_health_catching_up', 'Index catching up'),
        };
      }
      // healthy
      return {
        class: 'bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400',
        icon: 'mdi:check-circle',
        label: tf('fulltext_health_ok', 'Index healthy'),
      };
    });

    return { badge };
  },
});
</script>
