<template>
  <docbits-accordion-panel
    v-model="expanded"
    icon="mdi:database-search"
    :title="$t('fulltext_erp_indexing')"
  >
    <template #header-actions>
      <div class="flex items-center gap-1" @click.stop>
        <q-btn outline color="primary" icon="done_all" :label="$t('enable_all')" :loading="bulkLoading" @click="$emit('toggle-all', true)" />
        <q-btn outline color="primary" icon="remove_done" :label="$t('disable_all')" :loading="bulkLoading" @click="$emit('toggle-all', false)" />
      </div>
    </template>

    <!-- Loading (first mount only) -->
    <div v-if="loading" class="flex flex-col items-center justify-center py-8">
      <q-spinner-dots color="primary" size="40px" />
      <p class="mt-3 text-sm text-muted-foreground">{{ $t('loading') }}</p>
    </div>

    <!-- Error -->
    <div v-else-if="error" class="flex flex-col items-center justify-center py-8">
      <Icon icon="mdi:alert-circle-outline" class="size-10 text-destructive mb-2" />
      <p class="text-sm text-destructive">{{ error }}</p>
      <q-btn color="primary" no-caps class="mt-3" @click="$emit('reload')">
        <Icon icon="mdi:refresh" class="size-4 mr-1.5" />
        {{ $t('retry') }}
      </q-btn>
    </div>

    <!-- Data (aggregate hero + rows) -->
    <template v-else>
      <!-- Aggregate hero -->
      <div class="rounded-lg border border-border bg-muted/20 p-4 mb-4">
        <div class="flex flex-wrap items-center gap-3">
          <span
            class="inline-flex items-center gap-1.5 rounded-full px-2.5 py-0.5 text-xs font-semibold"
            :class="aggregateBadge.class"
          >
            <Icon :icon="aggregateBadge.icon" class="size-3.5" />
            {{ aggregateBadge.label }}
          </span>
          <span class="text-xs text-muted-foreground">
            {{ enabledEntityCount }} {{ tf('fulltext_erp_of', 'of') }} {{ settings.length }}
            {{ tf('fulltext_erp_entities_indexing', 'entities indexing') }}
          </span>
          <span class="text-xs text-muted-foreground ml-auto">
            {{ formatNumber(totalIndexedRecords) }}
            {{ tf('fulltext_erp_records_indexed', 'records indexed') }}
          </span>
        </div>
      </div>

      <!-- Styled row list -->
      <div class="divide-y divide-border">
        <div
          v-for="setting in settings"
          :key="setting.entity_type"
          class="flex flex-wrap items-center gap-3 py-2 px-1"
        >
          <!-- Label column -->
          <div class="flex flex-col flex-1 min-w-[120px]">
            <span class="text-sm font-medium text-foreground">
              {{ getEntityLabel(setting.entity_type) }}
            </span>
            <span class="text-xs text-muted-foreground">
              {{ getEntityDescription(setting.entity_type) }}
            </span>
          </div>

          <!-- Mini coverage bar + stats -->
          <div class="flex-1 min-w-[140px] max-w-[240px]">
            <div class="relative h-1.5 w-full rounded-full bg-muted overflow-hidden">
              <div
                class="h-full transition-[width] duration-300"
                :class="setting.enabled ? 'bg-primary' : 'bg-muted-foreground/20'"
                :style="{ width: setting.enabled ? entityPct(setting.entity_type) + '%' : '100%' }"
              />
            </div>
            <div class="text-[11px] text-muted-foreground mt-0.5">
              <template v-if="setting.enabled">
                {{ formatNumber(getStatForEntity(setting.entity_type)?.total_indexed ?? 0) }}
                / {{ formatNumber(getStatForEntity(setting.entity_type)?.in_database ?? 0) }}
                ({{ entityPct(setting.entity_type).toFixed(0) }}%)
                <span v-if="(getStatForEntity(setting.entity_type)?.with_vector ?? 0) > 0" class="ml-1">
                  · <Icon icon="mdi:chip" class="inline size-3" />
                  {{ formatNumber(getStatForEntity(setting.entity_type)?.with_vector ?? 0) }}
                </span>
              </template>
              <template v-else>
                {{ tf('fulltext_erp_disabled', 'indexing disabled') }}
              </template>
            </div>
          </div>

          <!-- Toggles -->
          <div class="flex items-center gap-2 shrink-0">
            <div class="flex items-center gap-1.5">
              <span class="text-[10px] text-muted-foreground">
                {{ tf('fulltext_erp_index', 'Index') }}
              </span>
              <q-toggle
                :model-value="setting.enabled"
                :loading="updatingSettings[setting.entity_type + '_indexing']"
                :disable="updatingSettings[setting.entity_type + '_indexing']"
                color="primary"
                size="sm"
                @update:model-value="(val) => $emit('update-indexing', setting.entity_type, val)"
              />
            </div>
            <div class="flex items-center gap-1.5">
              <span class="text-[10px] text-muted-foreground">
                {{ tf('fulltext_erp_vector', 'Vector') }}
              </span>
              <q-toggle
                :model-value="setting.vector_enabled"
                :loading="updatingSettings[setting.entity_type + '_vector']"
                :disable="!setting.enabled || updatingSettings[setting.entity_type + '_vector']"
                color="primary"
                size="sm"
                @update:model-value="(val) => $emit('update-vector', setting.entity_type, val)"
              />
            </div>
          </div>
        </div>
      </div>
    </template>
  </docbits-accordion-panel>
</template>

<script lang="ts">
import { computed, defineComponent, ref, type PropType } from 'vue';
import { Icon } from '@iconify/vue';
import { useTranslate } from '@tolgee/vue';
import DocbitsAccordionPanel from 'src/single-component/DocbitsAccordionPanel.vue';
import type { ERPIndexingSetting, EntityTypeStat } from 'src/services/settings/FulltextSettingsApiService';

export default defineComponent({
  name: 'ERPIndexingSection',

  components: {
    Icon,
    DocbitsAccordionPanel,
  },

  props: {
    settings: {
      type: Array as PropType<ERPIndexingSetting[]>,
      default: () => [],
    },
    loading: {
      type: Boolean,
      default: false,
    },
    statsLoading: {
      type: Boolean,
      default: false,
    },
    error: {
      type: String as PropType<string | null>,
      default: null,
    },
    bulkLoading: {
      type: Boolean,
      default: false,
    },
    updatingSettings: {
      type: Object as PropType<Record<string, boolean>>,
      default: () => ({}),
    },
    indexingInProgress: {
      type: Object as PropType<Record<string, { active: boolean }>>,
      default: () => ({}),
    },
    getEntityLabel: {
      type: Function as PropType<(entityType: string) => string>,
      required: true,
    },
    getEntityDescription: {
      type: Function as PropType<(entityType: string) => string>,
      required: true,
    },
    getStatForEntity: {
      type: Function as PropType<(entityType: string) => EntityTypeStat | null>,
      required: true,
    },
  },

  emits: ['toggle-all', 'update-indexing', 'update-vector', 'reload'],

  setup(props) {
    const expanded = ref(true);
    const { t } = useTranslate();

    const formatNumber = (num: number): string => {
      return num.toLocaleString();
    };

    const tf = (key: string, fallback: string): string => {
      const v = t.value(key);
      return v !== key ? v : fallback;
    };

    const enabledEntityCount = computed(() =>
      props.settings.filter((s) => s.enabled).length,
    );
    const totalIndexedRecords = computed(() =>
      props.settings.reduce((acc, s) => {
        const stat = props.getStatForEntity(s.entity_type);
        return acc + (stat?.total_indexed ?? 0);
      }, 0),
    );
    const aggregateBadge = computed(() => {
      if (enabledEntityCount.value === 0) {
        return {
          class: 'bg-muted text-muted-foreground',
          icon: 'mdi:information-outline',
          label: tf('fulltext_erp_all_disabled', 'ERP indexing disabled'),
        };
      }
      return {
        class: 'bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400',
        icon: 'mdi:check-circle',
        label: tf('fulltext_erp_active', 'ERP active'),
      };
    });

    const entityPct = (entityType: string) => {
      const stat = props.getStatForEntity(entityType);
      const total = stat?.in_database ?? 0;
      const idx = stat?.total_indexed ?? 0;
      if (!total) return 0;
      return Math.max(0, Math.min(100, (idx / total) * 100));
    };

    return {
      expanded,
      formatNumber,
      tf,
      enabledEntityCount,
      totalIndexedRecords,
      aggregateBadge,
      entityPct,
    };
  },
});
</script>

<style scoped></style>
