import { ref, reactive, onUnmounted } from 'vue';
import { notify } from 'src/components/notifications/notify';
import { useTranslate } from '@tolgee/vue';
import FulltextSettingsApiService, {
  ERPIndexingSetting,
  EntityTypeStat,
} from 'src/services/settings/FulltextSettingsApiService';

export function useERPIndexing(apiService: FulltextSettingsApiService) {
  const { t } = useTranslate();

  const settings = ref<ERPIndexingSetting[]>([]);
  const stats = ref<Record<string, EntityTypeStat>>({});
  const totals = ref<{
    total_indexed: number;
    with_vector: number;
    text_only: number;
    in_database: number;
  } | null>(null);
  const loading = ref(true);
  const statsLoading = ref(false);
  const error = ref<string | null>(null);
  const initialLoading = ref(true);
  const refreshing = ref(false);
  const lastUpdated = ref<Date | null>(null);
  // Scope: last successful fetch outcome. Transient per-entity update
  // failures log to console without setting this — the UI shouldn't
  // show a red state for every failed toggle.
  const bulkLoading = ref(false);
  const updatingSettings = reactive<Record<string, boolean>>({});
  const indexingInProgress = reactive<
    Record<string, { active: boolean; intervalId: ReturnType<typeof setInterval> | null }>
  >({});

  // Entity type labels and descriptions (translation keys)
  const entityTypeLabels: Record<string, string> = {
    vendor: 'fulltext_entity_vendor',
    customer: 'fulltext_entity_customer',
    material: 'fulltext_entity_material',
    bom: 'fulltext_entity_bom',
    purchase_order: 'fulltext_entity_purchase_order',
    sales_order: 'fulltext_entity_sales_order',
    invoice: 'fulltext_entity_invoice',
    shipment: 'fulltext_entity_shipment',
    service_ticket: 'fulltext_entity_service_ticket',
    attachment: 'attachments',
    email: 'fulltext_entity_email',
  };

  const entityTypeDescriptions: Record<string, string> = {
    vendor: 'fulltext_desc_vendor',
    customer: 'fulltext_desc_customer',
    material: 'fulltext_desc_material',
    bom: 'fulltext_desc_bom',
    purchase_order: 'fulltext_desc_purchase_order',
    sales_order: 'fulltext_desc_sales_order',
    invoice: 'fulltext_desc_invoice',
    shipment: 'fulltext_desc_shipment',
    service_ticket: 'fulltext_desc_service_ticket',
    attachment: 'fulltext_desc_attachment',
    email: 'fulltext_desc_email',
  };

  const getEntityLabel = (entityType: string): string => {
    const key = entityTypeLabels[entityType];
    return key ? t.value(key) : entityType;
  };

  const getEntityDescription = (entityType: string): string => {
    const key = entityTypeDescriptions[entityType];
    return key ? t.value(key) : '';
  };

  const getStatForEntity = (entityType: string): EntityTypeStat | null => {
    return stats.value[entityType] || null;
  };

  const loadStats = async () => {
    statsLoading.value = true;
    // Preserve last-good data; only flip initialLoading off at the end.
    if (Object.keys(stats.value).length > 0) {
      refreshing.value = true;
    }
    try {
      const response = await apiService.getERPStats();
      if (response.success && response.entity_stats) {
        const statsMap: Record<string, EntityTypeStat> = {};
        response.entity_stats.forEach((stat) => {
          statsMap[stat.entity_type] = stat;
        });
        stats.value = statsMap;
        if (response.totals) {
          totals.value = response.totals;
        }
        lastUpdated.value = new Date();
        error.value = null;
      }
    } catch (err: any) {
      error.value = err instanceof Error ? err.message : String(err);
      console.error('Failed to load ERP stats:', err);
    } finally {
      initialLoading.value = false;
      refreshing.value = false;
      statsLoading.value = false;
    }
  };

  const loadSettings = async () => {
    loading.value = true;
    // Preserve last-good data; only flip initialLoading off at the end.
    if (settings.value.length > 0) {
      refreshing.value = true;
    }
    try {
      const response = await apiService.getERPIndexingSettings();
      if (response.success) {
        settings.value = response.settings.map((s) => ({
          ...s,
          enabled: Boolean(s.enabled),
          vector_enabled: Boolean(s.vector_enabled),
        }));
        lastUpdated.value = new Date();
        error.value = null;
        loadStats();
      } else {
        error.value = response.message || t.value('error_loading_settings');
      }
    } catch (err: any) {
      error.value = err instanceof Error ? err.message : (err?.message || t.value('error_loading_settings'));
      console.error('Failed to load fulltext settings:', err);
    } finally {
      initialLoading.value = false;
      refreshing.value = false;
      loading.value = false;
    }
  };

  // Polling for per-entity indexing progress
  const stopIndexingPoll = (entityType: string) => {
    const poll = indexingInProgress[entityType];
    if (poll?.intervalId) {
      clearInterval(poll.intervalId);
    }
    indexingInProgress[entityType] = { active: false, intervalId: null };
  };

  const startIndexingPoll = (entityType: string) => {
    stopIndexingPoll(entityType);
    indexingInProgress[entityType] = {
      active: true,
      intervalId: setInterval(async () => {
        await loadStats();
        const stat = getStatForEntity(entityType);
        if (stat && stat.total_indexed >= stat.in_database) {
          stopIndexingPoll(entityType);
          notify.success(`${getEntityLabel(entityType)} - ${t.value('fulltext_indexing_complete') || 'Indexing complete'}`);
        }
      }, 3000),
    };
  };

  const stopAllIndexingPolls = () => {
    Object.keys(indexingInProgress).forEach(stopIndexingPoll);
  };

  const updateIndexingSetting = async (entityType: string, enabled: boolean) => {
    const key = entityType + '_indexing';
    updatingSettings[key] = true;

    try {
      const response = await apiService.updateERPIndexingSetting(entityType, enabled, undefined);
      if (response.success) {
        const setting = settings.value.find((s) => s.entity_type === entityType);
        if (setting) {
          setting.enabled = enabled;
        }
        if (enabled) {
          startIndexingPoll(entityType);
        } else {
          stopIndexingPoll(entityType);
        }
        notify.success(t.value('setting_updated_successfully'), { duration: 2000 });
      } else {
        notify.error(response.message || t.value('error_updating_setting'));
        await loadSettings();
      }
    } catch (err: any) {
      console.error('Failed to update indexing setting:', err);
      notify.error(err.message || t.value('error_updating_setting'));
      await loadSettings();
    } finally {
      updatingSettings[key] = false;
    }
  };

  const updateVectorSetting = async (entityType: string, vectorEnabled: boolean) => {
    const key = entityType + '_vector';
    updatingSettings[key] = true;

    try {
      const response = await apiService.updateERPIndexingSetting(entityType, undefined, vectorEnabled);
      if (response.success) {
        const setting = settings.value.find((s) => s.entity_type === entityType);
        if (setting) {
          setting.vector_enabled = vectorEnabled;
        }
        notify.success(t.value('setting_updated_successfully'), { duration: 2000 });
      } else {
        notify.error(response.message || t.value('error_updating_setting'));
        await loadSettings();
      }
    } catch (err: any) {
      console.error('Failed to update vector setting:', err);
      notify.error(err.message || t.value('error_updating_setting'));
      await loadSettings();
    } finally {
      updatingSettings[key] = false;
    }
  };

  const toggleAll = async (enabled: boolean) => {
    bulkLoading.value = true;

    try {
      const response = await apiService.toggleAllERPIndexing(enabled);
      if (response.success) {
        settings.value.forEach((s) => {
          s.enabled = enabled;
        });
        if (enabled) {
          settings.value.forEach((s) => startIndexingPoll(s.entity_type));
        } else {
          stopAllIndexingPolls();
        }
        notify.success(enabled ? t.value('all_settings_enabled') : t.value('all_settings_disabled'), { duration: 2000 });
      } else {
        notify.error(response.message || t.value('error_updating_settings'));
        await loadSettings();
      }
    } catch (err: any) {
      console.error('Failed to toggle all settings:', err);
      notify.error(err.message || t.value('error_updating_settings'));
      await loadSettings();
    } finally {
      bulkLoading.value = false;
    }
  };

  const cleanup = () => {
    stopAllIndexingPolls();
  };

  onUnmounted(cleanup);

  return {
    settings,
    stats,
    totals,
    loading,
    statsLoading,
    error,
    initialLoading,
    refreshing,
    lastUpdated,
    bulkLoading,
    updatingSettings,
    indexingInProgress,
    getEntityLabel,
    getEntityDescription,
    getStatForEntity,
    loadSettings,
    loadStats,
    updateIndexingSetting,
    updateVectorSetting,
    toggleAll,
    cleanup,
  };
}
