/**
 * Coverage percentage helper for /settings/fulltext hero line.
 *
 * Bug-2026-04-24 (coverage-display inconsistency): the hero used to
 * compute "Text %" against `in_database` and "Vector %" against
 * `total_indexed` — two different denominators for two numbers shown
 * side-by-side. For FELLOWPRO AG that rendered as
 * "Text 32.9% · Vector 100%" while 2 460 docs were still missing both.
 * Users read it as "Vector is done, Text is the bottleneck" — the
 * opposite of reality.
 *
 * Fix: always divide against `in_database`. Then "Text 32.9% · Vector
 * 32.9% · 2 460 missing" makes the real state obvious.
 *
 * Regression-locked in
 * ``__tests__/DocumentIndexingSection.coverage.unit.spec.ts``.
 */
export function coveragePct(numerator: number, denominator: number): number {
  if (!denominator) return 0;
  return Math.max(0, Math.min(100, (numerator / denominator) * 100));
}
