<template>
  <!-- Module Enable Dialog -->
  <q-dialog v-model="showEnableModal" persistent>
    <div class="rounded-lg border border-border bg-card shadow-lg w-full max-w-md">
      <div class="flex items-start gap-3 p-5 pb-3">
        <div class="settings-icon-box shrink-0">
          <Icon icon="mdi:text-search" height="24" width="24" />
        </div>
        <div>
          <h3 class="text-base font-semibold text-foreground">{{ $t('fulltext_module_required') }}</h3>
          <p class="text-sm text-muted-foreground mt-1">{{ $t('fulltext_module_not_enabled_message') }}</p>
        </div>
      </div>
      <div class="flex items-center justify-end gap-2 px-5 pb-4">
        <q-btn flat :label="$t('go_to_modules')" class="text-muted-foreground" @click="goToModules" />
        <q-btn class="f-btn" :label="$t('enable_now')" @click="initiateEnableModule" />
      </div>
    </div>
  </q-dialog>

  <!-- Subscription Dialog -->
  <SubscriptionDialog
    v-model="showSubscriptionPopup"
    :settings="user_settings"
    :settingType="open_search_enabled"
    :appKey="CONSTANTS.opensearch"
    :onConfirm="handleSubscriptionConfirm"
    @update:modelValue="(val) => { if (!val) cancelSubscription(); }"
  />

  <!-- Main Content -->
  <template v-if="moduleEnabled">
    <div class="page-container">
      <div class="settings-page-content space-y-4">
        <q-tabs
          v-model="activeTab"
          dense
          no-caps
          align="left"
          class="fulltext-tabs text-muted-foreground"
          active-color="primary"
          indicator-color="primary"
        >
          <q-tab name="documents" icon="mdi-file-document-outline" label="Documents" />
          <q-tab name="erp" icon="mdi-database-search-outline" label="ERP" />
          <q-tab name="templates" icon="mdi-file-code-outline" label="Templates" />
        </q-tabs>

        <q-tab-panels
          v-model="activeTab"
          animated
          class="fulltext-tab-panels"
        >
          <q-tab-panel name="documents">
            <DocumentIndexingSection
              :docStats="reindexState.docStats.value"
              :initialLoading="reindexState.initialLoading.value"
              :refreshing="reindexState.refreshing.value"
              :error="reindexState.error.value"
              :docReindexing="reindexState.docReindexing.value"
              :docReindexMode="reindexState.docReindexMode.value"
              :reindexProgress="reindexState.reindexProgress.value"
              :syncDiagnostics="reindexState.syncDiagnostics.value"
              :diagnosticsLoading="reindexState.diagnosticsLoading.value"
              :vectorPrefs="vectorPrefs"
              :vectorLoading="vectorLoading"
              :moduleCounts="moduleCounts"
              :streamStatus="reindexState.streamStatus.value"
              :streamLastEventAt="reindexState.streamLastEventAt.value"
              :indexDocsPerMinute="reindexState.indexDocsPerMinute.value"
              :indexETA="reindexState.indexETA.value"
              :lastFailure="reindexState.lastFailure.value"
              @load-stats="reindexState.loadDocumentStats"
              @load-diagnostics="reindexState.loadSyncDiagnostics"
              @reindex="reindexState.reindexDocuments"
              @dismiss-failure="reindexState.dismissLastFailure"
              @update-vector-pref="updateVectorPref"
            />
          </q-tab-panel>

          <q-tab-panel name="erp">
            <ERPIndexingSection
              :settings="erpState.settings.value"
              :loading="erpState.loading.value"
              :statsLoading="erpState.statsLoading.value"
              :error="erpState.error.value"
              :bulkLoading="erpState.bulkLoading.value"
              :updatingSettings="erpState.updatingSettings"
              :indexingInProgress="erpState.indexingInProgress"
              :getEntityLabel="erpState.getEntityLabel"
              :getEntityDescription="erpState.getEntityDescription"
              :getStatForEntity="erpState.getStatForEntity"
              @toggle-all="erpState.toggleAll"
              @update-indexing="erpState.updateIndexingSetting"
              @update-vector="erpState.updateVectorSetting"
              @reload="erpState.loadSettings"
            />
          </q-tab-panel>

          <q-tab-panel name="templates">
            <TemplateVersionsSection
              :templateVersions="reindexState.templateVersions.value"
            />
          </q-tab-panel>
        </q-tab-panels>

        <!--
          Bug 2026-05-02: removed AI Knowledge Base Indexing section.
          This page is /settings/fulltext — about document/vector
          fulltext search. AI knowledge bases are managed elsewhere
          (agent configuration page) and the read-only mirror here
          confused users into thinking it was actionable.
        -->
      </div>
    </div>

    <!-- Bug 2026-05-02: confirm dialog when user disables Vector Search
         while embeddings are still in the index. -->
    <DisableVectorConfirmDialog
      v-model="disableVectorDialogOpen"
      :vector-count="disableVectorCount"
      @choice="onDisableVectorChoice"
    />
  </template>

  <!-- Loading state while checking module status -->
  <div v-else-if="!showEnableModal" class="flex items-center justify-center" style="height: 50vh">
    <q-spinner-dots color="primary" size="40px" />
  </div>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent, ref, onMounted, onUnmounted, watch } from 'vue';
import { useTranslate } from '@tolgee/vue';
import { useRouter } from 'vue-router';
import { storeToRefs } from 'pinia';

import { Icon } from '@iconify/vue';

import SubscriptionDialog from 'src/pages/Settings/Components/Subscription/SubscriptionDialog.vue';
import DocumentIndexingSection from './FulltextSettings/DocumentIndexingSection.vue';
import ERPIndexingSection from './FulltextSettings/ERPIndexingSection.vue';
import TemplateVersionsSection from './FulltextSettings/TemplateVersionsSection.vue';
import DisableVectorConfirmDialog, {
  type DisableVectorChoice,
} from 'src/components/FulltextSettings/DisableVectorConfirmDialog.vue';

import FulltextSettingsApiService from 'src/services/settings/FulltextSettingsApiService';
import { useSettingStore, useSubscriptionStore } from 'src/store/main';
import { open_search_enabled, CONSTANTS } from 'src/constants';
import { fullSearchApiService } from 'src/services';

import { useReindexProgress } from 'src/composables/useReindexProgress';
import { useERPIndexing } from 'src/composables/useERPIndexing';
import { preferencesService } from 'src/services/preferences/preferencesService';

export default defineComponent({
  name: 'FulltextSettings',

  components: {
    Icon,
    SubscriptionDialog,
    DocumentIndexingSection,
    ERPIndexingSection,
    TemplateVersionsSection,
    DisableVectorConfirmDialog,
  },

  setup() {
    const { t } = useTranslate();
    const router = useRouter();
    const apiService = new FulltextSettingsApiService();
    const activeTab = ref<'documents' | 'erp' | 'templates'>('documents');

    // Composables
    const reindexState = useReindexProgress(apiService);
    const erpState = useERPIndexing(apiService);

    // Setting store for module status
    const settingStore = useSettingStore();
    const { user_settings, loading_settings } = storeToRefs(settingStore);
    const { updateSetting } = settingStore;

    // Module enable state
    const moduleEnabled = ref(false);
    const showEnableModal = ref(false);
    const showSubscriptionPopup = ref(false);
    const enablingModule = ref(false);
    const moduleStatusChecked = ref(false);

    // Vector preferences — three Org-level toggles that gate whether
    // vector embeddings are computed at index time. Keys match the
    // values Dashboard Filters reads to enable the `vector:` badge.
    const VECTOR_KEYS = [
      'OPENSEARCH_VECTOR_DOCUMENTS',
      'OPENSEARCH_VECTOR_INVOICES',
      'OPENSEARCH_VECTOR_ATTACHMENTS',
    ] as const;
    const vectorPrefs = ref<Record<string, boolean>>({
      OPENSEARCH_VECTOR_DOCUMENTS: false,
      OPENSEARCH_VECTOR_INVOICES: false,
      OPENSEARCH_VECTOR_ATTACHMENTS: false,
    });
    const vectorLoading = ref<Record<string, boolean>>({});

    // Per-module indexed/total counts. Empty for now — reserved for a
    // future backend per-module stats endpoint. The child falls back to
    // aggregate docStats values when a key is missing.
    const moduleCounts = ref<Record<string, { indexed: number; total: number }>>({});

    const loadVectorPrefs = async () => {
      await Promise.all(
        VECTOR_KEYS.map(async (key) => {
          const v = await preferencesService.getOrgPreference(key);
          vectorPrefs.value[key] = String(v).toLowerCase() === 'true';
        }),
      );
    };

    // Bug 2026-05-02: when disabling Vector Search for the documents
    // module while embeddings are still in the index, prompt the user
    // to choose between keeping or deleting the embeddings. See
    // DisableVectorConfirmDialog.vue + the new
    // /opensearch/admin/clear-vector-embeddings endpoint.
    const disableVectorDialogOpen = ref(false);
    const disableVectorPending = ref<{ key: string } | null>(null);
    const disableVectorCount = ref(0);

    const persistVectorPref = async (key: string, value: boolean) => {
      // Optimistic update so the toggle doesn't snap back while the
      // PUT is in flight. Revert on failure — preference couldn't be
      // saved, UI should reflect the server state.
      vectorLoading.value = { ...vectorLoading.value, [key]: true };
      const prev = vectorPrefs.value[key];
      vectorPrefs.value[key] = value;
      try {
        const res = await preferencesService.setOrgPreference(key, value);
        if (!res.success) {
          throw new Error(res.error || 'setOrgPreference failed');
        }
        notify.success(t.value('fulltext_vector_pref_saved') || 'Saved');

        // When document vector search is enabled and there are documents
        // without embeddings, kick off a background sync reindex automatically
        // so the user sees indexing start immediately.
        if (key === 'OPENSEARCH_VECTOR_DOCUMENTS' && value === true) {
          const stats = reindexState.docStats.value;
          const inDb = stats?.in_database ?? 0;
          const withVector = stats?.with_vector ?? 0;
          if (inDb > 0 && withVector < inDb && !reindexState.docReindexing.value) {
            reindexState.reindexDocuments('sync');
          }
        }

        return true;
      } catch (err: any) {
        vectorPrefs.value[key] = prev;
        notify.error(err?.message || 'Failed to update vector setting');
        return false;
      } finally {
        vectorLoading.value = { ...vectorLoading.value, [key]: false };
      }
    };

    const updateVectorPref = async (key: string, value: boolean) => {
      // Disable-flow with embeddings present: gate behind the confirm
      // dialog. All other transitions (enable, disable when nothing
      // indexed yet, non-document keys) go through the persist path
      // directly — no behaviour change.
      const withVectorCount = reindexState.docStats.value?.with_vector ?? 0;
      const isDisableDocsVector =
        key === 'OPENSEARCH_VECTOR_DOCUMENTS' &&
        value === false &&
        withVectorCount > 0;

      if (!isDisableDocsVector) {
        await persistVectorPref(key, value);
        return;
      }

      // Open the dialog. The choice handler will either persist+clear
      // or just persist or do nothing (cancel).
      disableVectorPending.value = { key };
      disableVectorCount.value = withVectorCount;
      disableVectorDialogOpen.value = true;
    };

    const onDisableVectorChoice = async (choice: DisableVectorChoice) => {
      const pending = disableVectorPending.value;
      disableVectorPending.value = null;
      if (!pending || choice === 'cancel') return;

      const ok = await persistVectorPref(pending.key, false);
      if (!ok) return;

      if (choice === 'disable-and-delete') {
        try {
          const res = await apiService.clearVectorEmbeddings();
          if (res.success) {
            notify.success(
              t.value('fulltext_vectors_cleared') ||
                `Removed ${res.modified_count ?? 0} vector embeddings`,
            );
            // Bug 2026-05-02: defensive UI cleanup — the backend now
            // also clears reindex_progress server-side, but the next
            // SSE tick is up to ~5s out. Drop the local
            // reindexProgress + lastFailure immediately so the user
            // sees "Indexing missing documents" panel + failure
            // banner disappear within the same animation frame as the
            // toggle flipping to off.
            reindexState.dismissLastFailure();
            reindexState.reindexProgress.value = null;
            // Refresh stats so the coverage bar + Vector% reflect the
            // new state. reindexState.loadDocumentStats is already
            // wired up — calling it triggers a re-render.
            await reindexState.loadDocumentStats();
          } else {
            notify.error(res.message || 'Failed to clear vector embeddings');
          }
        } catch (err: any) {
          notify.error(err?.message || 'Failed to clear vector embeddings');
        }
      }
    };

    // Module status check
    const checkModuleStatus = () => {
      moduleStatusChecked.value = true;
      moduleEnabled.value = Boolean(user_settings.value[open_search_enabled]);
      if (moduleEnabled.value) {
        showEnableModal.value = false;
        reindexState.loadDocumentStats();
        reindexState.checkActiveReindex();
        erpState.loadSettings();
        loadVectorPrefs();
      } else {
        showEnableModal.value = true;
      }
    };

    const goToModules = () => router.push('/settings/modules');

    const initiateEnableModule = () => {
      showEnableModal.value = false;
      showSubscriptionPopup.value = true;
    };

    const handleSubscriptionConfirm = async (value: boolean) => {
      enablingModule.value = true;

      // Set moduleEnabled early to prevent watcher from showing modal during settings reload
      if (value) {
        moduleEnabled.value = true;
        showEnableModal.value = false;
      }

      try {
        await useSubscriptionStore().saveSubscriptionChange(
          value,
          CONSTANTS.opensearch,
          () => {},
          updateSetting,
          (msg: string) => notify.error(msg),
          (msg: string) => notify.success(msg),
        );

        if (value) {
          await fullSearchApiService.createOpenSearchIndex();
        } else {
          // Disabling OpenSearch implies disabling Vector — semantic
          // embeddings need OpenSearch to function. Fire all three
          // vector-pref disables in parallel and update the local
          // mirror so the UI is consistent on next mount. The reverse
          // is asymmetric on purpose: enabling OpenSearch does NOT
          // auto-enable Vector — that stays an explicit user opt-in.
          await Promise.allSettled(
            VECTOR_KEYS.map((key) =>
              preferencesService.setOrgPreference(key, false),
            ),
          );
          VECTOR_KEYS.forEach((key) => {
            vectorPrefs.value[key] = false;
          });
        }

        showSubscriptionPopup.value = false;
        erpState.loadSettings();

        notify.success(t.value('fulltext_module_enabled'));
      } catch (err: any) {
        moduleEnabled.value = false;
        notify.error(err.message || t.value('error_enabling_module'), { duration: 3000 });
        showEnableModal.value = true;
      } finally {
        enablingModule.value = false;
      }
    };

    const cancelSubscription = () => {
      showSubscriptionPopup.value = false;
      showEnableModal.value = true;
    };

    onMounted(() => {
      if (!loading_settings.value) {
        checkModuleStatus();
      }
    });

    onUnmounted(() => {
      reindexState.cleanup();
      erpState.cleanup();
    });

    watch(loading_settings, (newVal, oldVal) => {
      if (oldVal === true && newVal === false) {
        checkModuleStatus();
      }
    });

    return {
      // Composable states (passed to children)
      reindexState,
      erpState,
      activeTab,
      // Vector preferences
      vectorPrefs,
      vectorLoading,
      updateVectorPref,
      // Disable-Vector confirm dialog (Bug 2026-05-02)
      disableVectorDialogOpen,
      disableVectorCount,
      onDisableVectorChoice,
      // Module counts (reserved for future per-module stats)
      moduleCounts,
      // Module enable
      moduleEnabled,
      showEnableModal,
      showSubscriptionPopup,
      enablingModule,
      user_settings,
      open_search_enabled,
      CONSTANTS,
      goToModules,
      initiateEnableModule,
      handleSubscriptionConfirm,
      cancelSubscription,
    };
  },
});
</script>

<style scoped>
/*
  The shared DocbitsAccordionPanel has two nested paddings:
  .settings-accordion-body (outer gray band, 1.25rem 1.5rem) and
  .slot-body (inner white card, same padding again). Drop the outer
  padding on the Fulltext page so the white card extends to the
  accordion's own border — more breathing room for the chart and cards.
*/
:deep(.settings-accordion-body) {
  padding: 0 !important;
}

:deep(.slot-body) {
  border-radius: 0;
}

.fulltext-tabs {
  border-bottom: 1px solid hsl(var(--border));
  background: hsl(var(--card));
}

.fulltext-tab-panels {
  background: transparent;
}

:deep(.fulltext-tab-panels .q-tab-panel) {
  padding: 0;
  padding-top: 16px;
}
</style>
