<template>
  <!--
    Bug 2026-05-02: 3-button confirm dialog when the user disables Vector
    Search while embeddings are still in the index. Quasar's built-in
    `$q.dialog()` only supports OK / Cancel — this custom q-dialog is
    needed to expose a third "Disable + Delete embeddings" option that
    flips the pref AND fires the `clear-vector-embeddings` endpoint.

    Behaviour mirrors the `confirmFullRebuild` pattern in
    DocumentIndexingSection.vue:413 (persistent: true, two-line message
    explaining the trade-off, color-coded buttons).
  -->
  <q-dialog v-model="visible" persistent>
    <q-card class="max-w-md">
      <q-card-section class="flex items-start gap-3">
        <Icon
          icon="mdi:alert-outline"
          class="size-6 text-amber-600 shrink-0 mt-0.5"
        />
        <div class="flex-1">
          <div class="text-base font-medium">
            {{ tf('fulltext_disable_vector_title', 'Disable Vector Search') }}
          </div>
          <div class="mt-2 text-sm text-muted-foreground">
            {{
              tf(
                'fulltext_disable_vector_body',
                `You currently have ${formattedCount} vector embeddings indexed. What would you like to do?`,
              ).replace('{count}', formattedCount)
            }}
          </div>
          <ul class="mt-3 text-xs text-muted-foreground space-y-1.5 list-disc pl-4">
            <li>
              <span class="font-medium text-foreground">{{
                tf('fulltext_disable_only', 'Disable only')
              }}</span>
              —
              {{
                tf(
                  'fulltext_disable_only_hint',
                  'keep embeddings, just stop using them for search. Re-enabling later is instant.',
                )
              }}
            </li>
            <li>
              <span class="font-medium text-foreground">{{
                tf('fulltext_disable_and_delete', 'Disable + Delete embeddings')
              }}</span>
              —
              {{
                tf(
                  'fulltext_disable_and_delete_hint',
                  'free up storage. Re-enabling later requires a full vector rebuild.',
                )
              }}
            </li>
          </ul>
        </div>
      </q-card-section>

      <q-card-actions align="right" class="gap-1">
        <q-btn
          flat
          no-caps
          color="grey-7"
          @click="onChoice('cancel')"
        >
          {{ tf('fulltext_disable_cancel', 'Cancel') }}
        </q-btn>
        <q-btn
          flat
          no-caps
          color="primary"
          @click="onChoice('disable-only')"
        >
          {{ tf('fulltext_disable_only', 'Disable only') }}
        </q-btn>
        <q-btn
          unelevated
          no-caps
          color="negative"
          @click="onChoice('disable-and-delete')"
        >
          <Icon icon="mdi:delete-outline" class="size-4 mr-1" />
          {{ tf('fulltext_disable_and_delete', 'Disable + Delete embeddings') }}
        </q-btn>
      </q-card-actions>
    </q-card>
  </q-dialog>
</template>

<script lang="ts">
import { defineComponent, ref, computed, watch } from 'vue';
import { useTranslate } from '@tolgee/vue';
import { Icon } from '@iconify/vue';

export type DisableVectorChoice = 'cancel' | 'disable-only' | 'disable-and-delete';

export default defineComponent({
  name: 'DisableVectorConfirmDialog',
  components: { Icon },
  props: {
    modelValue: { type: Boolean, default: false },
    vectorCount: { type: Number, default: 0 },
  },
  emits: ['update:modelValue', 'choice'],
  setup(props, { emit }) {
    const { t } = useTranslate();
    const tf = (key: string, fallback: string): string => {
      const v = t.value(key);
      return v !== key ? v : fallback;
    };

    const visible = ref(props.modelValue);
    watch(
      () => props.modelValue,
      (val) => {
        visible.value = val;
      },
    );
    watch(visible, (val) => {
      emit('update:modelValue', val);
    });

    const formattedCount = computed(() => props.vectorCount.toLocaleString());

    const onChoice = (choice: DisableVectorChoice) => {
      emit('choice', choice);
      visible.value = false;
    };

    return { tf, visible, formattedCount, onChoice };
  },
});
</script>
