<!-- src/components/FulltextSettings/DiagnosticsPanel.vue -->
<template>
  <div class="rounded-md border border-border bg-muted/10 px-3 py-2">
    <div
      class="flex items-center gap-2 cursor-pointer select-none"
      @click="$emit('update:expanded', !expanded)"
    >
      <Icon icon="mdi:information-outline" class="size-4 text-amber-500" />
      <span class="text-xs text-muted-foreground flex-1">
        {{ tf('fulltext_why_not_indexed', 'Why are some documents not indexed?') }}
        ({{ formatNumber(missingCount) }} {{ tf('fulltext_missing', 'missing') }})
      </span>
      <q-btn
        flat
        dense
        round
        size="xs"
        :loading="loading"
        @click.stop="$emit('reload')"
      >
        <Icon icon="mdi:sync" class="size-3.5 text-muted-foreground" />
      </q-btn>
      <Icon
        icon="mdi:chevron-down"
        class="size-4 text-muted-foreground transition-transform duration-200"
        :class="{ 'rotate-180': expanded }"
      />
    </div>

    <div v-if="expanded" class="mt-3">
      <div v-if="loading && !diagnostics" class="flex justify-center py-4">
        <q-spinner-dots color="primary" size="24px" />
      </div>

      <div v-else-if="diagnostics" class="space-y-3">
        <div class="grid grid-cols-3 gap-3">
          <div class="text-center">
            <div class="text-lg font-semibold text-amber-500">
              {{ formatNumber(diagnostics.diagnostics.breakdown.no_s3_file) }}
            </div>
            <div class="text-xs text-muted-foreground">
              {{ tf('fulltext_diag_no_s3', 'No S3 file') }}
            </div>
          </div>
          <div class="text-center">
            <div class="text-lg font-semibold text-primary">
              {{ formatNumber(diagnostics.diagnostics.breakdown.processing_incomplete) }}
            </div>
            <div class="text-xs text-muted-foreground">
              {{ tf('fulltext_diag_processing', 'Still processing') }}
            </div>
          </div>
          <div class="text-center">
            <div class="text-lg font-semibold text-destructive">
              {{ formatNumber(diagnostics.diagnostics.breakdown.indexing_failed) }}
            </div>
            <div class="text-xs text-muted-foreground">
              {{ tf('fulltext_diag_failed', 'Indexing failed') }}
            </div>
          </div>
        </div>

        <div v-if="diagnostics.diagnostics.recent_failures.length > 0">
          <div class="text-xs font-medium text-destructive flex items-center gap-1 mb-1.5">
            <Icon icon="mdi:alert-circle" class="size-3.5" />
            {{ tf('fulltext_recent_failures', 'Recent failures') }}
          </div>
          <div class="space-y-1">
            <div
              v-for="doc in diagnostics.diagnostics.recent_failures.slice(0, 10)"
              :key="doc.doc_id"
              class="text-xs rounded-md border border-border bg-background px-2.5 py-1.5"
            >
              <div class="flex flex-wrap items-center gap-x-2 gap-y-1">
                <span class="font-medium text-foreground">{{ doc.filename || doc.doc_id }}</span>
                <span class="rounded bg-destructive/10 px-1.5 py-0.5 text-[10px] font-medium uppercase tracking-wide text-destructive">
                  {{ reasonLabel(doc.reason) }}
                </span>
                <span class="text-muted-foreground">
                  {{ tf('fulltext_doc_status', 'Doc status') }}: {{ doc.status }}
                </span>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent, type PropType } from 'vue';
import { useTranslate } from '@tolgee/vue';
import { Icon } from '@iconify/vue';
import type { SyncDiagnosticsResponse } from 'src/services/settings/FulltextSettingsApiService';

export default defineComponent({
  name: 'DiagnosticsPanel',
  components: { Icon },
  props: {
    expanded: { type: Boolean, default: false },
    loading: { type: Boolean, default: false },
    missingCount: { type: Number, required: true },
    diagnostics: { type: Object as PropType<SyncDiagnosticsResponse | null>, default: null },
  },
  emits: ['update:expanded', 'reload'],
  setup() {
    const { t } = useTranslate();
    const tf = (k: string, f: string) => {
      const v = t.value(k);
      return v !== k ? v : f;
    };
    const formatNumber = (n: number) => n.toLocaleString();
    const reasonLabel = (reason?: string) => {
      switch (reason) {
        case 'indexing_failed':
          return tf('fulltext_reason_indexing_failed', 'Indexing failed');
        case 'edoc_indexing_failed':
          return tf('fulltext_reason_edoc_indexing_failed', 'E-Doc indexing failed');
        case 'no_s3_file':
          return tf('fulltext_reason_no_s3', 'Source file missing');
        default:
          return reason || tf('fulltext_reason_unknown', 'Unknown');
      }
    };
    return { tf, formatNumber, reasonLabel };
  },
});
</script>
