<template>
  <docbits-accordion-panel
    v-model="expanded"
    icon="mdi:file-document-outline"
    :title="$t('fulltext_document_indexing')"
  >
    <template #header-actions>
      <q-btn
        flat
        dense
        round
        size="sm"
        :loading="refreshing && !docReindexing"
        @click.stop="loadDocumentStats"
      >
        <Icon icon="mdi:refresh" class="size-4 text-muted-foreground" />
        <q-tooltip>{{ $t('refresh') }}</q-tooltip>
      </q-btn>
    </template>

    <!-- Initial skeleton — rendered only on first mount before any data -->
    <template v-if="initialLoading">
      <div class="space-y-4">
        <div class="rounded-lg border border-border bg-muted/20 p-4">
          <div class="h-4 w-1/3 rounded bg-muted animate-pulse mb-2">
          </div>
          <div class="h-6 w-full rounded bg-muted animate-pulse">
          </div>
        </div>
        <div class="grid grid-cols-1 sm:grid-cols-3 gap-2">
          <div v-for="i in 3" :key="i" class="h-24 rounded-md border border-border bg-muted animate-pulse">
          </div>
        </div>
      </div>
    </template>

    <template v-else>
      <!-- Hero row: status + aggregate numbers -->
      <div class="mb-3">
        <div class="flex flex-wrap items-center gap-3 mb-3">
          <IndexHealthBadge
            :index-pct="indexCoveragePct"
            :vector-pct="vectorCoveragePct"
            :any-vector-enabled="anyVectorEnabled"
            :reindex-active="docReindexing"
            :failed-count="recentFailedCount"
          />
          <!-- Bug-2026-04-29: SSE-Sichtbarkeits-Pill — User sieht
               jetzt sofort ob die Live-Stream-Verbindung lebt
               (live/reconnecting/fallback/offline). Vorher war
               ein hängender Stream optisch identisch zum
               normalen Idle-State. -->
          <StreamStatusPill
            :status="streamStatus"
            :last-event-at="streamLastEventAt"
          />
          <span class="text-xs text-muted-foreground">
            {{ formatNumber(docStats?.in_database ?? 0) }}
            {{ tf('fulltext_docs_in_db_short', 'documents in database') }}
          </span>
        </div>

        <!--
          DocBits dual-lane card: Text index (left) + Vector index (right).
          "Operations cockpit" aesthetic — refined typography, tabular
          nums, subtle hover lift, shimmering bar when active. Each lane
          is a self-contained channel monitor with its own primary action.
        -->
        <div class="lane-grid mb-3">
          <!-- DOCUMENTS (SLIM) LANE — Phase 5 rename: this lane reflects
               the slim documents index (metadata + IDs only) introduced
               in Phase 1-4.  Was previously labelled "Text Index" before
               the heavy-fields split moved OCR/AI text to its own
               companion index. -->
          <article
            class="lane-card"
            :class="{ 'lane-active': textSyncActive }"
          >
            <header class="lane-header">
              <div class="flex items-center gap-2">
                <span class="lane-icon lane-icon-text">
                  <Icon icon="mdi:file-document-outline" class="size-4" />
                </span>
                <span class="lane-label">
                  {{ tf('fulltext_documents_slim_index', 'Documents (slim)') }}
                </span>
              </div>
              <span class="lane-chip lane-chip-positive">
                {{ tf('fulltext_lane_always_on', 'Always on') }}
              </span>
            </header>

            <div class="lane-readout">
              <span class="lane-percent">{{ indexCoveragePct.toFixed(1) }}<span class="lane-percent-unit">%</span></span>
              <span class="lane-fraction">
                {{ formatNumber(docStats?.total_indexed ?? 0) }} {{ tf('fulltext_indexed_short', 'indexed') }}
              </span>
            </div>

            <div
              class="lane-bar"
              :class="{ 'lane-bar-active': textSyncActive }"
            >
              <div
                class="lane-bar-fill"
                :style="{ width: Math.min(100, indexCoveragePct) + '%' }"
              />
            </div>

            <div class="lane-status">
              <span v-if="missingCount > 0" class="lane-status-warn">
                <Icon icon="mdi:circle-medium" class="size-4 -ml-1" />
                {{ formatNumber(missingCount) }} {{ tf('fulltext_missing', 'missing') }}
              </span>
              <span v-else class="lane-status-ok">
                <Icon icon="mdi:check" class="size-3.5" />
                {{ tf('fulltext_complete', 'complete') }}
              </span>
            </div>

            <q-btn
              outline
              color="primary"
              size="sm"
              no-caps
              class="lane-action"
              :disable="docReindexing || missingCount === 0"
              @click="reindexDocuments('sync')"
            >
              <Icon icon="mdi:sync" class="size-3.5 mr-1" />
              {{ tf('fulltext_index_missing_action', 'Index missing documents') }}
            </q-btn>
          </article>

          <!-- VECTOR LANE -->
          <article
            class="lane-card"
            :class="{
              'lane-disabled': !documentsVectorEnabled,
              'lane-active': vectorSyncActive,
            }"
          >
            <header class="lane-header">
              <div class="flex items-center gap-2">
                <span
                  class="lane-icon"
                  :class="documentsVectorEnabled ? 'lane-icon-vector' : 'lane-icon-muted'"
                >
                  <Icon icon="mdi:chip" class="size-4" />
                </span>
                <span class="lane-label">
                  {{ tf('fulltext_vector_index', 'Vector Index') }}
                </span>
              </div>
              <q-toggle
                size="sm"
                :model-value="!!vectorPrefs.OPENSEARCH_VECTOR_DOCUMENTS"
                :loading="!!vectorLoading.OPENSEARCH_VECTOR_DOCUMENTS"
                @update:model-value="(val) => onToggleVector('OPENSEARCH_VECTOR_DOCUMENTS', val)"
              >
                <q-tooltip class="text-xs" max-width="240px">
                  {{ tf('fulltext_vector_search_desc', 'AI-powered similarity search on top of keyword. Higher storage + GPU embedding cost.') }}
                </q-tooltip>
              </q-toggle>
            </header>

            <template v-if="!documentsVectorEnabled">
              <div class="lane-empty">
                <Icon icon="mdi:power-plug-off-outline" class="size-5 text-muted-foreground" />
                <span>
                  {{ tf('fulltext_vector_disabled_hint', 'Semantic search is off. Enable to index document embeddings for similarity search.') }}
                </span>
              </div>
            </template>
            <template v-else>
              <div class="lane-readout">
                <span class="lane-percent">{{ vectorCoveragePct.toFixed(1) }}<span class="lane-percent-unit">%</span></span>
                <span class="lane-fraction">
                  {{ formatNumber(docStats?.with_vector ?? 0) }} {{ tf('fulltext_embedded_short', 'embedded') }}
                </span>
              </div>
              <div
                class="lane-bar"
                :class="{ 'lane-bar-active': vectorSyncActive }"
              >
                <div
                  class="lane-bar-fill"
                  :style="{ width: Math.min(100, vectorCoveragePct) + '%' }"
                />
              </div>
              <div class="lane-status">
                <span v-if="missingVectorCount > 0" class="lane-status-warn">
                  <Icon icon="mdi:circle-medium" class="size-4 -ml-1" />
                  {{ formatNumber(missingVectorCount) }} {{ tf('fulltext_missing', 'missing') }}
                </span>
                <span v-else class="lane-status-ok">
                  <Icon icon="mdi:check" class="size-3.5" />
                  {{ tf('fulltext_complete', 'complete') }}
                </span>
              </div>
              <q-btn
                outline
                color="primary"
                size="sm"
                no-caps
                class="lane-action"
                :disable="docReindexing || missingCount > 0 || missingVectorCount === 0"
                @click="reindexDocuments('sync')"
              >
                <Icon icon="mdi:chip" class="size-3.5 mr-1" />
                {{ tf('fulltext_rebuild_vectors_action', 'Rebuild Vectors') }}
              </q-btn>
            </template>
          </article>

          <!-- FULLTEXT TEXT COMPANION LANE — Phase 5: new third lane
               for the heavy-fields companion index (`*_text_v1`).
               Holds OCR pages, AI text, tfidf state.  Backfilled
               separately from the slim documents rebuild so search
               returns to a working state in minutes; this lane catches
               up over the following hours.  Backend field
               `text_companion_indexed` is optional — pre-Phase-5
               backends emit no count and the lane shows "—" with the
               template-status hint. -->
          <article
            class="lane-card"
            :class="{
              'lane-active': textCompanionSyncActive,
            }"
          >
            <header class="lane-header">
              <div class="flex items-center gap-2">
                <span
                  class="lane-icon"
                  :class="textCompanionAvailable ? 'lane-icon-fulltext' : 'lane-icon-muted'"
                >
                  <Icon icon="mdi:text-box-search-outline" class="size-4" />
                </span>
                <span class="lane-label">
                  {{ tf('fulltext_text_companion_index', 'Fulltext (text)') }}
                </span>
              </div>
              <span
                v-if="!textCompanionAvailable"
                class="lane-chip lane-chip-warn"
              >
                {{ tf('fulltext_lane_backfill_pending', 'Backfill pending') }}
              </span>
              <span v-else class="lane-chip lane-chip-positive">
                {{ tf('fulltext_lane_always_on', 'Always on') }}
              </span>
            </header>

            <div class="lane-readout">
              <span class="lane-percent">
                {{ textCompanionCoveragePct.toFixed(1) }}<span class="lane-percent-unit">%</span>
              </span>
              <span class="lane-fraction">
                {{ formatNumber(textCompanionIndexed) }} {{ tf('fulltext_indexed_short', 'indexed') }}
              </span>
            </div>
            <div
              class="lane-bar"
              :class="{ 'lane-bar-active': textCompanionSyncActive }"
            >
              <div
                class="lane-bar-fill"
                :style="{ width: Math.min(100, textCompanionCoveragePct) + '%' }"
              />
            </div>
            <div class="lane-status">
              <span v-if="missingTextCompanionCount > 0" class="lane-status-warn">
                <Icon icon="mdi:circle-medium" class="size-4 -ml-1" />
                {{ formatNumber(missingTextCompanionCount) }} {{ tf('fulltext_missing', 'missing') }}
              </span>
              <span v-else class="lane-status-ok">
                <Icon icon="mdi:check" class="size-3.5" />
                {{ tf('fulltext_complete', 'complete') }}
              </span>
            </div>
            <q-btn
              outline
              color="primary"
              size="sm"
              no-caps
              class="lane-action"
              :disable="docReindexing || missingTextCompanionCount === 0"
              @click="reindexDocuments('sync')"
            >
              <Icon icon="mdi:text-box-search-outline" class="size-3.5 mr-1" />
              {{ tf('fulltext_rebuild_text_companion_action', 'Backfill text companion') }}
            </q-btn>
            <div
              v-if="!textCompanionAvailable"
              class="lane-hint"
            >
              {{ tf('fulltext_text_companion_pending_short', 'OCR text backfill has not reported coverage yet.') }}
            </div>
          </article>
        </div>

        <!--
          Bug-2026-05-01 (Ruiz Foods incident): when ERP-bulk hogs the
          worker pool, the doc index counter only ticks ~0.1/min instead
          of the expected 16+. The static hero "X / Y indexed" didn't
          make that visible to admins. This row exposes the live rate
          and ETA so the user can immediately see "stuck (0/min)" vs
          "16/min, fertig 09:45". Hidden when there's nothing missing
          and rate is 0 — both healthy and irrelevant.
        -->
        <div
          v-if="!nothingToIndex && (reindexProgress?.active || missingCount > 0 || (indexDocsPerMinute !== null && indexDocsPerMinute > 0))"
          class="-mt-1 flex items-center gap-2 text-xs"
        >
          <Icon
            :icon="indexDocsPerMinute === 0 ? 'mdi:alert-outline' : 'mdi:speedometer'"
            :class="indexDocsPerMinute === 0 ? 'size-3.5 text-amber-600' : 'size-3.5 text-muted-foreground'"
          />
          <span v-if="indexDocsPerMinute === null" class="text-muted-foreground">
            {{ tf('fulltext_velocity_warming', 'Measuring indexing rate…') }}
          </span>
          <span v-else-if="indexDocsPerMinute === 0" class="text-amber-600">
            {{ tf('fulltext_velocity_stuck', 'Indexing stuck — 0 docs/min') }}
            <span v-if="missingCount > 0" class="text-muted-foreground">
              · {{ formatNumber(missingCount) }} {{ tf('fulltext_missing', 'missing') }}
            </span>
          </span>
          <span v-else class="text-muted-foreground">
            <span class="font-medium text-foreground">
              {{ indexDocsPerMinute.toFixed(1) }} {{ tf('fulltext_velocity_unit', 'docs/min') }}
            </span>
            <span v-if="indexETA && missingCount > 0">
              · {{ tf('fulltext_velocity_eta', 'ETA') }}
              <span class="font-medium text-foreground">{{ formatETAWithTf(indexETA) }}</span>
            </span>
          </span>
        </div>
      </div>

        <!-- Error banner (stale-while-revalidate) -->
        <div
          v-if="error"
          class="mt-1.5 mb-2 flex items-center gap-2 text-xs text-amber-600"
        >
          <Icon icon="mdi:alert-outline" class="size-3.5" />
          {{ tf('fulltext_refresh_failed', 'Refresh failed') }}
          <a class="underline cursor-pointer ml-auto" @click="loadDocumentStats">
            {{ tf('retry', 'Retry') }}
          </a>
        </div>

      <!--
        Bug 2026-05-02: persistent failure banner from useReindexProgress.
        Replaces the old `notify.error` toast spam that hammered every
        SSE tick when the backend kept replaying a cached failed state.
        Banner stays until the user retries or dismisses.
      -->
      <LastReindexFailureBanner
        v-if="lastFailure"
        :failure="lastFailure"
        @retry="$emit('reindex', lastFailure.mode === 'full' ? 'full' : 'sync')"
        @dismiss="$emit('dismiss-failure')"
      />

      <!--
        Live progress panel — render whenever the BACKEND reports an active
        reindex, regardless of who triggered it. Bug-2026-05-01 (user):
        background auto-heal beat starts a sync without any UI click in
        this tab; the old `docReindexing` gate kept the panel hidden so
        the user only saw counters tick up but never the ETA / rate. Now
        we also accept `reindexProgress.active` from the SSE/poll snapshot.
      -->
      <!--
        Bug 2026-05-02: when vector search is enabled, the progress panel
        showed job-level counters (10 / 3,903) while the coverage bar showed
        OpenSearch stats (20 / 3,547). Pass docStats so the panel can render
        consistent vector counts when vector mode is active.
      -->
      <LiveProgressPanel
        v-if="!nothingToIndex && reindexProgress?.progress && (docReindexing || reindexProgress?.active)"
        class="mb-3"
        :mode="liveProgressMode"
        :total="reindexProgress.progress.total ?? docStats?.in_database ?? 0"
        :processed="reindexProgress.progress.processed ?? 0"
        :indexed="reindexProgress.progress.indexed ?? 0"
        :failed="reindexProgress.progress.failed ?? 0"
        :percent-complete="liveProgressPercent"
        :started-at="reindexStartedAt"
        :eta-date="indexETA"
        :rate-per-minute="indexDocsPerMinute"
        :vector-enabled="liveProgressVectorEnabled"
        :in-database="docStats?.in_database ?? 0"
        :with-vector="docStats?.with_vector ?? 0"
      />

      <!-- Diagnostics (collapsed by default, only when missing > 0) -->
      <!--
        Hide DiagnosticsPanel during active reindex: the "Recent failures"
        bucket assumes "doc has S3 file but is missing from OpenSearch =
        permanent indexing failure". During a reindex (especially after a
        Full Rebuild), every doc is transiently missing while the queue
        catches up — labelling them all "Indexing failed" is misleading.
        Show diagnostics only when the system is idle and still has gaps.
      -->
      <DiagnosticsPanel
        v-if="hasMissingDocuments && !reindexProgress?.active"
        class="mb-3"
        :expanded="diagnosticsExpanded"
        :loading="diagnosticsLoading"
        :missing-count="missingCount"
        :diagnostics="syncDiagnostics"
        @update:expanded="onDiagnosticsToggle"
        @reload="loadSyncDiagnostics"
      />

      <!--
        Destructive escape hatch only — primary "Index missing" and
        "Rebuild Vectors" actions live inside their respective lane
        cards above. Full Rebuild stays separate because it's the
        destructive option (drops + recreates the entire index).
      -->
      <div class="flex flex-wrap items-center justify-end gap-2">
        <div class="flex-1" />

        <q-btn
          color="negative"
          no-caps
          :disable="docReindexing"
          @click="confirmFullRebuild"
        >
          <Icon icon="mdi:delete-restore" class="size-4 mr-1.5" />
          {{ tf('fulltext_full_rebuild_action', 'Full Rebuild') }}
          <q-tooltip class="text-xs" max-width="280px">
            {{ tf('fulltext_full_rebuild_tooltip_new', 'Destroys the current search index and rebuilds from scratch. Guarantees every document is present with the current settings (text + vector if enabled). Slow but deterministic.') }}
          </q-tooltip>
        </q-btn>
      </div>
    </template>
  </docbits-accordion-panel>
</template>

<script lang="ts">
import { defineComponent, ref, computed, watch, type PropType } from 'vue';
import { useTranslate } from '@tolgee/vue';
import { useQuasar } from 'quasar';
import { Icon } from '@iconify/vue';
import DocbitsAccordionPanel from 'src/single-component/DocbitsAccordionPanel.vue';
import IndexHealthBadge from 'src/components/FulltextSettings/IndexHealthBadge.vue';
import StreamStatusPill from 'src/components/FulltextSettings/StreamStatusPill.vue';
import LiveProgressPanel from 'src/components/FulltextSettings/LiveProgressPanel.vue';
import LastReindexFailureBanner from 'src/components/FulltextSettings/LastReindexFailureBanner.vue';
import DiagnosticsPanel from 'src/components/FulltextSettings/DiagnosticsPanel.vue';
import { coveragePct } from './coverage';
import { formatETA } from 'src/utils/formatETA';
import type {
  ReindexProgressResponse,
  SyncDiagnosticsResponse,
  DocumentStatsResponse,
} from 'src/services/settings/FulltextSettingsApiService';

export default defineComponent({
  name: 'DocumentIndexingSection',
  components: {
    Icon,
    DocbitsAccordionPanel,
    IndexHealthBadge,
    StreamStatusPill,
    LiveProgressPanel,
    LastReindexFailureBanner,
    DiagnosticsPanel,
  },
  props: {
    docStats: {
      type: Object as PropType<DocumentStatsResponse['stats'] | null>,
      default: null,
    },
    initialLoading: { type: Boolean, default: false },
    refreshing: { type: Boolean, default: false },
    error: { type: Object as PropType<Error | null>, default: null },
    docReindexing: { type: Boolean, default: false },
    docReindexMode: {
      type: String as PropType<'sync' | 'full' | null>,
      default: null,
    },
    reindexProgress: {
      type: Object as PropType<ReindexProgressResponse | null>,
      default: null,
    },
    syncDiagnostics: {
      type: Object as PropType<SyncDiagnosticsResponse | null>,
      default: null,
    },
    diagnosticsLoading: { type: Boolean, default: false },
    vectorPrefs: {
      type: Object as PropType<Record<string, boolean>>,
      default: () => ({}),
    },
    vectorLoading: {
      type: Object as PropType<Record<string, boolean>>,
      default: () => ({}),
    },
    moduleCounts: {
      type: Object as PropType<Record<string, { indexed: number; total: number }>>,
      default: () => ({}),
    },
    // Bug-2026-04-29: SSE stream lifecycle for the Pill rendered in
    // the hero row. Driven by `useReindexProgress` composable on the
    // parent page.
    streamStatus: {
      type: String as PropType<
        'connecting' | 'live' | 'reconnecting' | 'fallback' | 'error'
      >,
      default: 'connecting',
    },
    streamLastEventAt: {
      type: Object as PropType<Date | null>,
      default: null,
    },
    // Bug-2026-05-01: rolling indexing rate + ETA so the user can see
    // immediately whether the index is making progress or stuck. Both
    // null while the rolling window warms up; rate=0 means observed
    // standstill (counter unchanged for ≥60s).
    indexDocsPerMinute: {
      type: Number as PropType<number | null>,
      default: null,
    },
    indexETA: {
      type: Object as PropType<Date | null>,
      default: null,
    },
    // Bug-2026-05-02: persistent failed-state banner. Driven by the
    // `lastFailure` ref in `useReindexProgress`. Null = no banner.
    lastFailure: {
      type: Object as PropType<NonNullable<ReindexProgressResponse['progress']> | null>,
      default: null,
    },
  },
  emits: ['load-stats', 'load-diagnostics', 'reindex', 'update-vector-pref', 'dismiss-failure'],
  setup(props, { emit }) {
    const { t } = useTranslate();
    const $q = useQuasar();
    const expanded = ref(true);
    const diagnosticsExpanded = ref(false);
    const reindexStartedAt = ref<number>(Date.now());

    const tf = (key: string, fallback: string): string => {
      const translated = t.value(key);
      return translated !== key ? translated : fallback;
    };
    const formatNumber = (n: number) => n.toLocaleString('en-US');

    // formatETA hoisted to src/utils/formatETA.ts so LiveProgressPanel can
    // share the same absolute-time output. Local closure binds `tf`.
    const formatETAWithTf = (eta: Date | null) => formatETA(eta, tf);

    // Bug-2026-04-24: both percentages MUST share the same denominator
    // (in_database) so they are directly comparable in the hero line.
    // Previously Vector% was against total_indexed, which made it read
    // "Vector 100% · Text 32.9%" even though ~2400 docs were missing
    // both. See coverage.ts + its test for the full rationale.
    const indexCoveragePct = computed(() =>
      coveragePct(
        props.docStats?.total_indexed ?? 0,
        props.docStats?.in_database ?? 0,
      ),
    );
    const vectorCoveragePct = computed(() =>
      coveragePct(
        props.docStats?.with_vector ?? 0,
        props.docStats?.in_database ?? 0,
      ),
    );
    const hasMissingDocuments = computed(() =>
      (props.docStats?.in_database ?? 0) > (props.docStats?.total_indexed ?? 0),
    );
    const missingCount = computed(() =>
      Math.max(0, (props.docStats?.in_database ?? 0) - (props.docStats?.total_indexed ?? 0)),
    );
    const missingVectorCount = computed(() =>
      Math.max(0, (props.docStats?.in_database ?? 0) - (props.docStats?.with_vector ?? 0)),
    );
    const recentFailedCount = computed(() =>
      props.reindexProgress?.progress?.failed ?? 0,
    );

    // Reset reindex start time when a reindex begins so ETA is accurate
    watch(
      () => props.docReindexing,
      (now, prev) => {
        if (now && !prev) reindexStartedAt.value = Date.now();
      },
    );

    const loadDocumentStats = () => emit('load-stats');
    const loadSyncDiagnostics = () => emit('load-diagnostics');

    // Prefetch diagnostics as soon as we know there's something to explain.
    // The endpoint scans documents for breakdown counts and can take a few
    // seconds — kicking it off in the background means the panel shows
    // data instantly when the user expands it instead of making them wait.
    watch(
      hasMissingDocuments,
      (has) => {
        if (has && !props.syncDiagnostics && !props.diagnosticsLoading) {
          loadSyncDiagnostics();
        }
      },
      { immediate: true },
    );
    const reindexDocuments = (mode: 'sync' | 'full') => emit('reindex', mode);

    const confirmFullRebuild = () => {
      $q.dialog({
        title: tf('fulltext_full_rebuild_confirm_title', 'Full rebuild'),
        message: tf(
          'fulltext_full_rebuild_confirm_body',
          'This will wipe the current search index and rebuild every document from scratch. The index will be unavailable for the duration. Continue?',
        ),
        cancel: true,
        persistent: true,
        ok: { label: tf('fulltext_full_rebuild_confirm_ok', 'Rebuild'), color: 'warning' },
      }).onOk(() => reindexDocuments('full'));
    };

    const vectorScopes = computed(() => [
      {
        key: 'OPENSEARCH_VECTOR_DOCUMENTS',
        label: tf('fulltext_vector_documents', 'Documents'),
        description: tf('fulltext_vector_documents_desc', 'All document bodies'),
        indexed: props.moduleCounts['OPENSEARCH_VECTOR_DOCUMENTS']?.indexed ?? (props.docStats?.total_indexed ?? 0),
        total: props.moduleCounts['OPENSEARCH_VECTOR_DOCUMENTS']?.total ?? (props.docStats?.in_database ?? 0),
      },
      {
        key: 'OPENSEARCH_VECTOR_INVOICES',
        label: tf('fulltext_vector_invoices', 'Invoices'),
        description: tf('fulltext_vector_invoices_desc', 'Invoice-specific fields'),
        indexed: props.moduleCounts['OPENSEARCH_VECTOR_INVOICES']?.indexed ?? 0,
        total: props.moduleCounts['OPENSEARCH_VECTOR_INVOICES']?.total ?? 0,
      },
      {
        key: 'OPENSEARCH_VECTOR_ATTACHMENTS',
        label: tf('fulltext_vector_attachments', 'Attachments'),
        description: tf('fulltext_vector_attachments_desc', 'Email / PO attachments'),
        indexed: props.moduleCounts['OPENSEARCH_VECTOR_ATTACHMENTS']?.indexed ?? 0,
        total: props.moduleCounts['OPENSEARCH_VECTOR_ATTACHMENTS']?.total ?? 0,
      },
    ]);

    const anyVectorEnabled = computed(() =>
      vectorScopes.value.some((s) => props.vectorPrefs[s.key]),
    );

    // Bug 2026-05-02: the Vector Index hero card is about the documents
    // tier specifically — keep the card-level boolean separate from the
    // any-of-three rollup used by IndexHealthBadge / status hints.
    const documentsVectorEnabled = computed(
      () => !!props.vectorPrefs?.OPENSEARCH_VECTOR_DOCUMENTS,
    );

    // Document and vector use the same backend `sync` operation, but the
    // worker now runs it as two phases: text documents first, vectors only
    // after the text index is complete. Keep the UI on the active phase so
    // it doesn't show two unrelated spinners for one queue job.
    const syncReindexing = computed(
      () => props.docReindexing && props.docReindexMode === 'sync',
    );
    const textSyncActive = computed(
      () => syncReindexing.value && missingCount.value > 0,
    );
    const vectorSyncActive = computed(
      () =>
        syncReindexing.value &&
        documentsVectorEnabled.value &&
        missingCount.value === 0 &&
        missingVectorCount.value > 0,
    );

    // Phase 5: heavy-text companion lane.  Backend may not yet emit
    // `text_companion_indexed` — degrade gracefully.  We treat the lane
    // as "available" once the backend exposes the count OR the template
    // status confirms the text index exists.  The active flag fires
    // when the worker is in the third (text) phase of a sync rebuild
    // (documents complete + vectors complete + text catch-up).
    const textCompanionIndexed = computed(
      () => Number(props.docStats?.text_companion_indexed ?? 0),
    );
    const textCompanionAvailable = computed(() => {
      const stats = props.docStats;
      const fromCount =
        stats !== null
        && stats !== undefined
        && stats.text_companion_indexed !== undefined
        && stats.text_companion_indexed !== null;
      return fromCount;
    });
    const textCompanionCoveragePct = computed(() =>
      coveragePct(
        textCompanionIndexed.value,
        props.docStats?.in_database ?? 0,
      ),
    );
    const missingTextCompanionCount = computed(() =>
      Math.max(
        0,
        (props.docStats?.in_database ?? 0) - textCompanionIndexed.value,
      ),
    );
    const textCompanionSyncActive = computed(
      () =>
        syncReindexing.value
        && missingCount.value === 0
        && missingVectorCount.value === 0
        && missingTextCompanionCount.value > 0,
    );
    const liveProgressMode = computed<'sync' | 'full' | 'vectors'>(() => {
      if (props.docReindexMode === 'full') return 'full';
      return vectorSyncActive.value ? 'vectors' : 'sync';
    });
    const liveProgressPercent = computed(() =>
      vectorSyncActive.value
        ? vectorCoveragePct.value
        : (props.reindexProgress?.progress?.percent_complete ?? indexCoveragePct.value),
    );
    const liveProgressVectorEnabled = computed(() => vectorSyncActive.value);

    // Bug-2026-05-02: when documents-vector is disabled AND text-index is
    // already 100%, there is nothing left to index. Defensive frontend
    // gate against stale Redis progress (cascade-dropped tasks, races,
    // older backends that didn't write a terminal status). Without this,
    // the user sees a phantom "Indexing missing documents — stuck" card
    // that can only be cleared by the backend stale-detector after 5min.
    const nothingToIndex = computed(() => {
      const inDb = props.docStats?.in_database ?? 0;
      const indexed = props.docStats?.total_indexed ?? 0;
      const textComplete = inDb > 0 && inDb === indexed;
      return textComplete && !documentsVectorEnabled.value;
    });

    const onToggleVector = (key: string, val: boolean) => {
      emit('update-vector-pref', key, val);
    };
    const onDiagnosticsToggle = (val: boolean) => {
      diagnosticsExpanded.value = val;
      // Data is prefetched by the watcher above as soon as missing > 0,
      // so this fallback only fires if the prefetch somehow failed.
      if (val && !props.syncDiagnostics && !props.diagnosticsLoading) {
        loadSyncDiagnostics();
      }
    };

    return {
      expanded,
      diagnosticsExpanded,
      reindexStartedAt,
      tf,
      formatNumber,
      formatETAWithTf,
      indexCoveragePct,
      vectorCoveragePct,
      hasMissingDocuments,
      missingCount,
      missingVectorCount,
      recentFailedCount,
      loadDocumentStats,
      loadSyncDiagnostics,
      reindexDocuments,
      confirmFullRebuild,
      vectorScopes,
      anyVectorEnabled,
      documentsVectorEnabled,
      textSyncActive,
      vectorSyncActive,
      textCompanionIndexed,
      textCompanionAvailable,
      textCompanionCoveragePct,
      missingTextCompanionCount,
      textCompanionSyncActive,
      liveProgressMode,
      liveProgressPercent,
      liveProgressVectorEnabled,
      nothingToIndex,
      onToggleVector,
      onDiagnosticsToggle,
    };
  },
});
</script>

