<template>
  <span
    class="inline-flex items-center gap-1.5 rounded-full px-2 py-0.5 text-[11px] font-medium"
    :class="pill.class"
    :title="pill.tooltip"
  >
    <Icon :icon="pill.icon" :class="['size-3', { 'animate-pulse': pill.pulse }]" />
    <span>{{ pill.label }}</span>
    <span v-if="lastEventLabel" class="opacity-70">· {{ lastEventLabel }}</span>
  </span>
</template>

<script lang="ts">
import { defineComponent, computed, ref, onMounted, onUnmounted, type PropType } from 'vue';
import { useTranslate } from '@tolgee/vue';
import { Icon } from '@iconify/vue';

/**
 * Bug-2026-04-29: visualisiert den Status der SSE-Verbindung zur
 * Settings-Page. Ohne diese Pill hatte der User KEIN Feedback ob
 * der Live-Stream lebt — bei silent failures (Token expired, CORS,
 * Backend-hang) sah die Seite identisch aus zur "alles fein, idle"
 * Variante. Jetzt sieht der User sofort:
 *
 *   🟢 Live updates · 3s ago     — alles gut
 *   🟡 Reconnecting…             — temporärer Drop, EventSource retried
 *   🟠 Polling (every 2s)        — SSE permanent tot, Fallback läuft
 *   🔴 Stream offline            — kein Connect, refresh notwendig
 *   ⚪ Connecting…               — initial, vor erstem Event
 *
 * Plus "last update Xs ago" damit User merkt wenn der Stream still
 * eingefroren ist (was bei einem Backend-hang passieren würde).
 */
export default defineComponent({
  name: 'StreamStatusPill',
  components: { Icon },
  props: {
    status: {
      type: String as PropType<
        'connecting' | 'live' | 'reconnecting' | 'fallback' | 'error'
      >,
      required: true,
    },
    lastEventAt: {
      type: Object as PropType<Date | null>,
      default: null,
    },
  },
  setup(props) {
    const { t } = useTranslate();
    const tf = (k: string, f: string) => {
      const v = t.value(k);
      return v !== k ? v : f;
    };

    // Tick a seconds-counter every 1s so the "X seconds ago" label
    // re-renders without polling other state.
    const now = ref(Date.now());
    let tickHandle: ReturnType<typeof setInterval> | null = null;
    onMounted(() => {
      tickHandle = setInterval(() => {
        now.value = Date.now();
      }, 1000);
    });
    onUnmounted(() => {
      if (tickHandle !== null) clearInterval(tickHandle);
    });

    const pill = computed(() => {
      switch (props.status) {
        case 'live':
          return {
            class: 'bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400',
            icon: 'mdi:circle-medium',
            label: tf('fulltext_stream_live', 'Live updates'),
            tooltip: tf(
              'fulltext_stream_live_tooltip',
              'Server-Sent Events stream is connected. Counters update in real time.',
            ),
            pulse: true,
          };
        case 'reconnecting':
          return {
            class: 'bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-400',
            icon: 'mdi:sync',
            label: tf('fulltext_stream_reconnecting', 'Reconnecting…'),
            tooltip: tf(
              'fulltext_stream_reconnecting_tooltip',
              'Connection dropped, browser is retrying. Status will update once it reconnects.',
            ),
            pulse: false,
          };
        case 'fallback':
          return {
            class: 'bg-orange-100 text-orange-700 dark:bg-orange-900/30 dark:text-orange-400',
            icon: 'mdi:timer-outline',
            label: tf('fulltext_stream_fallback', 'Polling (every 2s)'),
            tooltip: tf(
              'fulltext_stream_fallback_tooltip',
              'Live stream not available — falling back to HTTP polling. Updates may lag a few seconds.',
            ),
            pulse: false,
          };
        case 'error':
          return {
            class: 'bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400',
            icon: 'mdi:close-circle-outline',
            label: tf('fulltext_stream_offline', 'Stream offline'),
            tooltip: tf(
              'fulltext_stream_offline_tooltip',
              'Cannot connect to the live status stream. Refresh the page to retry.',
            ),
            pulse: false,
          };
        case 'connecting':
        default:
          return {
            class: 'bg-gray-100 text-gray-600 dark:bg-gray-800/50 dark:text-gray-400',
            icon: 'mdi:lan-pending',
            label: tf('fulltext_stream_connecting', 'Connecting…'),
            tooltip: tf(
              'fulltext_stream_connecting_tooltip',
              'Opening the live status stream.',
            ),
            pulse: true,
          };
      }
    });

    const lastEventLabel = computed(() => {
      if (!props.lastEventAt) return '';
      const ageMs = now.value - props.lastEventAt.getTime();
      if (ageMs < 2000) return tf('fulltext_stream_just_now', 'just now');
      if (ageMs < 60000) {
        const s = Math.floor(ageMs / 1000);
        return tf('fulltext_stream_seconds_ago', '{n}s ago').replace('{n}', String(s));
      }
      const m = Math.floor(ageMs / 60000);
      return tf('fulltext_stream_minutes_ago', '{n}m ago').replace('{n}', String(m));
    });

    return { pill, lastEventLabel };
  },
});
</script>
