<template>
  <!--
    Bug 2026-05-02: persistent failure banner for the last failed indexing
    run. Replaces the old `notify.error` toast spam that fired on every SSE
    tick when the backend kept replaying the cached failed state. The user
    sees ONE actionable banner with the actual diagnostic message + age,
    and decides whether to retry or dismiss.
  -->
  <div
    class="mb-3 rounded-md border border-destructive/40 bg-destructive/5 p-3 text-xs flex items-start gap-3"
  >
    <Icon
      icon="mdi:alert-circle-outline"
      class="size-5 text-destructive shrink-0 mt-0.5"
    />
    <div class="flex-1 min-w-0">
      <div class="font-medium text-destructive">
        {{ tf('fulltext_failure_banner_title', 'Last indexing run failed') }}
      </div>
      <div class="mt-0.5 text-muted-foreground break-words">
        <span v-if="processedOf">
          {{
            tf('fulltext_failure_stalled_at', 'stalled at')
          }}
          <span class="font-medium text-foreground">{{ processedOf }}</span>
        </span>
        <span v-if="ageText" class="ml-1">
          ({{ ageText }})
        </span>
        <div v-if="failure.message" class="mt-0.5 italic">
          {{ failure.message }}
        </div>
      </div>
    </div>
    <div class="flex items-center gap-1 shrink-0">
      <q-btn
        flat
        dense
        no-caps
        size="sm"
        color="primary"
        @click="$emit('retry')"
      >
        <Icon icon="mdi:reload" class="size-4 mr-1" />
        {{ tf('fulltext_failure_banner_retry', 'Retry') }}
      </q-btn>
      <q-btn
        flat
        dense
        round
        size="sm"
        color="grey-7"
        @click="$emit('dismiss')"
      >
        <Icon icon="mdi:close" class="size-4" />
        <q-tooltip class="text-xs">
          {{ tf('fulltext_failure_banner_dismiss', 'Dismiss') }}
        </q-tooltip>
      </q-btn>
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent, computed, type PropType } from 'vue';
import { useTranslate } from '@tolgee/vue';
import { Icon } from '@iconify/vue';
import type { ReindexProgressResponse } from 'src/services/settings/FulltextSettingsApiService';

type FailureProgress = NonNullable<ReindexProgressResponse['progress']>;

export default defineComponent({
  name: 'LastReindexFailureBanner',
  components: { Icon },
  props: {
    failure: {
      type: Object as PropType<FailureProgress>,
      required: true,
    },
  },
  emits: ['retry', 'dismiss'],
  setup(props) {
    const { t } = useTranslate();
    const tf = (key: string, fallback: string): string => {
      const v = t.value(key);
      return v !== key ? v : fallback;
    };

    const processedOf = computed(() => {
      const p = props.failure.processed ?? 0;
      const total = props.failure.total ?? 0;
      if (!total) return '';
      return `${p.toLocaleString()} / ${total.toLocaleString()}`;
    });

    // Render an "8 min ago" style age. updated_at is an ISO string from the
    // backend (executer.update_reindex_progress writes datetime.utcnow().isoformat()).
    const ageText = computed(() => {
      if (!props.failure.updated_at) return '';
      const t0 = Date.parse(props.failure.updated_at + 'Z'); // backend writes naive UTC
      if (isNaN(t0)) return '';
      const ms = Date.now() - t0;
      if (ms < 60_000) return `${Math.round(ms / 1000)}s ago`;
      if (ms < 3_600_000) return `${Math.round(ms / 60_000)} min ago`;
      const h = Math.round(ms / 3_600_000);
      return `${h} h ago`;
    });

    return { tf, processedOf, ageText };
  },
});
</script>
