<template>
  <div class="rounded-lg border border-border bg-muted/20 p-4">
    <div class="flex items-center justify-between mb-2">
      <span class="inline-flex items-center gap-2 text-sm font-medium text-foreground">
        <Icon icon="mdi:sync" class="size-4 text-primary animate-spin-slow" />
        {{ modeLabel }}
      </span>
      <span v-if="cancellable" class="text-xs">
        <a class="text-primary underline cursor-pointer" @click="$emit('cancel')">
          {{ tf('fulltext_cancel', 'Cancel') }}
        </a>
      </span>
    </div>

    <div class="flex items-center gap-4">
      <div class="shrink-0" style="width: 100px; height: 100px;">
        <ApexChart type="radialBar" height="100" :options="ringOptions" :series="[percentComplete]" />
        <span class="sr-only">{{ percentRounded }}%</span>
      </div>

      <div class="flex-1 text-xs space-y-1">
        <div>
          <span class="font-medium text-foreground">
            <template v-if="vectorEnabled">
              {{ formatNumber(withVector) }} / {{ formatNumber(inDatabase) }}
            </template>
            <template v-else>
              {{ formatNumber(processed) }} / {{ formatNumber(total) }}
            </template>
          </span>
          <span class="text-muted-foreground ml-1">
            <template v-if="vectorEnabled">
              {{ tf('fulltext_with_vector', 'with vector') }}
            </template>
            <template v-else>
              {{ tf('fulltext_processed', 'processed') }}
            </template>
          </span>
        </div>
        <!--
          Bug-2026-05-01: prefer the rolling-window ETA from useReindexProgress
          when the parent passes it down. It samples backend snapshots over
          a 5-minute window so it survives transient throughput dips and can
          render a duration like "ETA in 2h 15m" instead of the naive
          "ETA ~5m 30s" we'd compute from `processed / elapsedSec` (which
          starts measuring at UI mount, not at sync-start, and lies wildly
          for background-triggered syncs).
        -->
        <!--
          Bug 2026-05-05: never derive ETA from `processed / elapsedSec`.
          In sync mode `processed` is cumulative coverage, not "docs since
          this panel mounted"; a freshly-mounted panel at 545/4300 can
          otherwise show impossible rates like 840 docs/s.
        -->
        <div v-if="etaDate" class="text-muted-foreground">
          {{ tf('fulltext_eta_duration', 'ETA') }}
          <span class="font-medium text-foreground">{{ formatEtaAbsolute(etaDate) }}</span>
          <span v-if="ratePerMinute !== null && ratePerMinute > 0">
            · {{ ratePerMinute.toFixed(1) }} {{ tf('fulltext_velocity_unit', 'docs/min') }}
          </span>
        </div>
        <div v-else-if="ratePerMinute === 0" class="text-amber-600">
          {{ tf('fulltext_velocity_stuck', 'Indexing stuck — 0 docs/min') }}
        </div>
        <div v-else class="text-muted-foreground">
          {{ tf('fulltext_velocity_warming', 'Measuring indexing rate…') }}
        </div>
        <div class="flex gap-4 pt-1">
          <span class="flex items-center gap-1 text-green-600 dark:text-green-400">
            <Icon icon="mdi:check-circle" class="size-3" />
            <template v-if="vectorEnabled">
              {{ formatNumber(withVector) }} {{ tf('fulltext_with_vector_label', 'with vector') }}
            </template>
            <template v-else>
              {{ formatNumber(indexed) }} {{ tf('fulltext_indexed_label', 'indexed') }}
            </template>
          </span>
          <span v-if="failed > 0" class="flex items-center gap-1 text-destructive">
            <Icon icon="mdi:alert-circle" class="size-3" />
            {{ formatNumber(failed) }} {{ tf('fulltext_failed_label', 'failed') }}
          </span>
        </div>
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent, computed, type PropType } from 'vue';
import { useTranslate } from '@tolgee/vue';
import { Icon } from '@iconify/vue';
import ApexChart from 'vue3-apexcharts';
import type { ApexOptions } from 'apexcharts';
import { formatETA } from 'src/utils/formatETA';

export default defineComponent({
  name: 'LiveProgressPanel',
  components: { Icon, ApexChart },
  props: {
    mode: { type: String as () => 'sync' | 'full' | 'vectors', required: true },
    total: { type: Number, required: true },
    processed: { type: Number, required: true },
    indexed: { type: Number, required: true },
    failed: { type: Number, required: true },
    percentComplete: { type: Number, required: true },
    startedAt: { type: Number, required: true }, // ms epoch
    cancellable: { type: Boolean, default: false },
    // Bug-2026-05-01: when the parent has a rolling-window-derived ETA,
    // prefer it over the naive `processed/elapsedSec` calc. Both null
    // is fine — the component falls back to its own estimate.
    etaDate: { type: Object as PropType<Date | null>, default: null },
    ratePerMinute: { type: Number as PropType<number | null>, default: null },
    // Bug 2026-05-02: pass OpenSearch stats so the panel shows consistent
    // vector counts instead of job-level counters that diverge from the
    // coverage bar and ModuleCoverageCard.
    vectorEnabled: { type: Boolean, default: false },
    inDatabase: { type: Number, default: 0 },
    withVector: { type: Number, default: 0 },
  },
  emits: ['cancel'],
  setup(props) {
    const { t } = useTranslate();
    const tf = (k: string, f: string) => {
      const v = t.value(k);
      return v !== k ? v : f;
    };
    const formatNumber = (n: number) => n.toLocaleString();
    const formatEtaAbsolute = (eta: Date | null) => formatETA(eta, tf);
    const percentRounded = computed(() => Math.round(props.percentComplete));

    const modeLabel = computed(() => {
      if (props.mode === 'full') return tf('fulltext_mode_full', 'Full rebuild');
      if (props.mode === 'vectors') return tf('fulltext_mode_vectors', 'Rebuild vectors');
      return tf('fulltext_mode_sync', 'Indexing missing documents');
    });

    // DocBits CSS vars hold full color values, not shadcn HSL triples,
    // so use them directly rather than wrapping in hsl().
    const resolveColor = (cssVar: string, fallback: string) => {
      if (typeof getComputedStyle === 'undefined') return fallback;
      const v = getComputedStyle(document.documentElement).getPropertyValue(cssVar).trim();
      return v || fallback;
    };

    const ringOptions = computed<ApexOptions>(() => ({
      chart: { sparkline: { enabled: true } },
      plotOptions: {
        radialBar: {
          hollow: { size: '60%' },
          track: { background: resolveColor('--muted', '#f1f5f9') },
          dataLabels: {
            name: { show: false },
            value: {
              fontSize: '18px',
              fontWeight: 600,
              color: resolveColor('--foreground', '#0f172a'),
              formatter: (v: number) => `${Math.round(v)}%`,
            },
          },
        },
      },
      colors: [resolveColor('--primary', '#2388AE')],
      stroke: { lineCap: 'round' },
    }));

    return { modeLabel, ringOptions, tf, formatNumber, formatEtaAbsolute, percentRounded };
  },
});
</script>

<style scoped>
@keyframes spin-slow {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}
.animate-spin-slow {
  animation: spin-slow 2.5s linear infinite;
}
</style>
